'use strict';
// 500 deterministic story identities, built from five world arcs and ten chapter beats.
// Reusable rescue mechanics are explicit: these are not 500 bespoke cinematic scripts.
const Rescue=(()=>{
const arcs=[
{place:'Desert County',hub:'the community garage',people:['Inez','Tariq','Lena','Omar','Rosa','Eli','Nadia','Sam','Ada','Theo'],sites:['Old Pump','Dry Creek','Radio Hill','County Diner','Water Tower','Rail Crossing','Dust Market','West Bridge','Canyon Gate','Last Outpost'],need:'reopen the garage before the county roads close',end:'Another light comes on at the garage.'},
{place:'Frostbite Pass',hub:'the mountain shelter',people:['Anya','Pavel','Mina','Soren','Eva','Luca','Niko','Freya','Ida','Lev'],sites:['North Lodge','Frozen Lake','Signal Cabin','Pine Bend','Snow Depot','Ice Bridge','Ridge Station','Tunnel Mouth','Summit Road','White Beacon'],need:'keep the mountain shelter warm through the storm',end:'A cold room at the shelter becomes warm again.'},
{place:'Neon Harbor',hub:'the harbor clinic',people:['Mei','Jules','Ren','Ari','Sol','Yuna','Kai','Noor','Bo','Zoe'],sites:['Pier One','Canal Steps','Night Market','Ferry Gate','Crane Yard','Blue Arcade','Cargo Lane','Lighthouse','East Wharf','Last Ferry'],need:'keep the harbor clinic open for the night shift',end:'The clinic opens another room for the harbor workers.'},
{place:'Ember Badlands',hub:'the evacuation workshop',people:['Amal','Dara','Luis','Asha','Remy','Iman','Pia','Kian','Vera','Enzo'],sites:['Ash Farm','Copper Mine','Heat Station','Red Viaduct','South Quarry','Glass Flats','Firebreak','Old Foundry','Ember Ridge','Safe Crossing'],need:'repair the evacuation vehicles before the next ashfall',end:'One more evacuation vehicle is ready to leave.'},
{place:'Verdant Ruins',hub:'the riverside home',people:['Alma','Davi','Esme','Finn','Hana','Isla','Jo','Luz','Milo','Nia'],sites:['River Steps','Moss Gate','Temple Road','Canopy Camp','Stone School','Broken Aqueduct','Garden Wall','Green Bridge','Hidden Dock','Home Road'],need:'reconnect families separated by the flooded roads',end:'Another family finds a safe road back home.'}
];
const beats=[
['The light beyond the smoke','Smoke has cut off the usual way home. They are waiting at the agreed meeting point, worried that nobody heard their call.','Meet people beyond the smoke; leave fire response to trained crews.'],
['A live wire, a quiet road','A fallen cable has closed their route. They stayed back with a neighbor rather than risk one last crossing.','Keep away from fallen cables and use a different route.'],
['The other side of the water','Rising water has separated them from the people expecting them. They chose dry ground and kept their signal visible.','Use a dry pickup point; do not enter floodwater to make a shortcut.'],
['The voice on the radio','A stranger sent them a new pickup location. They asked Jun to check the message before leaving the familiar meeting place.','Confirm changed pickup instructions through a known contact.'],
['A message asking too much','A message promised a ride in exchange for a private access code. They refused, but their phone is nearly empty.','Keep passwords and access codes private, even when a message sounds urgent.'],
['The locked medicine case','A sealed medical supply case needs a lift to the community team. They kept it closed while waiting for a trained worker.','Transport sealed supplies; let qualified people handle medicines.'],
['The gate beside the pool','They stayed outside a closed waterside gate and called for help. A companion is waiting with them on the safe side.','Arrange pickup away from the water; leave water rescue to trained responders.'],
['The road that can wait','A damaged crossing would make the journey shorter. They chose to wait rather than lead their neighbor onto it.','A closed crossing is a reason to reroute, not a challenge to beat.'],
['A landmark in the dark','Their battery is fading. Before the signal disappeared, they described a landmark Jun remembered from childhood.','Agree on a visible landmark and confirm where help is meeting you.'],
['One last confirmed call','The district is almost clear. They asked a known community helper to confirm who would collect the last people waiting.','Verify the pickup and keep the group together at the meeting point.']
];
// Each world hides one mystery. Every rescued person adds a sighting; every 10th level reveals a clue.
const mysteries=[
{subject:'Dad’s tow truck',hint:'a tow truck with one headlight',question:'Where did Dad’s tow truck go the night the porch light went out?',clues:['Tow-chain marks lead away from Old Pump. Dad’s truck passed here after the light went out.','At Dry Creek, Dad’s thermos sits on a flat stone, set down carefully like a marker.','Radio Hill logged one last call from Dad’s truck: “Keep the porch light ready.”','The County Diner kept Dad’s tab open: ten coffees, one for every driver he towed home that night.','Fresh chalk arrows on the Water Tower ladder point west. Dad always drew arrows for lost drivers.','In the Rail Crossing signal box: Dad’s jacket, and a note. “Not lost. Helping.”','Dust Market traders say a tow truck has pulled stranded cars out of the canyon every night.','West Bridge is closed. The tire tracks stop before it. Dad chose to wait, just like he taught you.','Beyond Canyon Gate, a single headlight blinks three times. Dad’s old signal: “I’m okay.”','At the Last Outpost, Dad’s truck stands with its lights on. He stayed to guide everyone out. Now he rides home with you.']},
{subject:'the White Beacon voice',hint:'a lantern up on the ridge',question:'Who keeps the White Beacon broadcasting through the storm?',clues:['Every night at nine, a calm voice reads the pass forecast from somewhere up the mountain.','The voice warned that Frozen Lake was thin before any ranger knew.','The Signal Cabin logbook is signed “K.” The same letter is carved into the shelter door.','Pine Bend’s children say the voice once hummed the shelter’s old lullaby.','Firewood stacked at the Snow Depot, with a note: “For the shelter. — K.”','The voice called the Ice Bridge closure minutes before it cracked.','Ridge Station’s radio is tuned to a channel only the old shelter keepers used.','At the Tunnel Mouth, slow, steady boot prints climb toward the summit. One person, alone.','A snowplow driver on Summit Road sees a lantern in the beacon tower every night.','At the White Beacon: Katya, the shelter’s first keeper, guiding the pass alone. Tonight she comes down to the warm room you rebuilt.']},
{subject:'the last ferry',hint:'a ferry light in the fog',question:'Why did the last ferry never dock?',clues:['The tide board at Pier One still shows the last ferry as “ARRIVING.”','Canal Steps vendors heard its horn in the fog: three short blasts, then silence.','A ticket stub from the ferry turns up at the Night Market, stamped with tomorrow’s date.','Ferry Gate cameras caught the ferry turning away from the dock, toward the clinic side of the bay.','The Crane Yard operator says the ferry radioed for a doctor before the lockdown.','A crew jacket hangs by the Blue Arcade door, soaked in salt water.','Cargo Lane workers found the ferry’s medical kit, delivered to the wrong pier.','The Lighthouse keeper kept the beam on all night, guiding a slow boat toward East Wharf.','At East Wharf, the moorings are freshly tied. Someone docked quietly in the dark.','At the Last Ferry berth: the crew carried a newborn and her mother straight to the clinic. It stayed open because you kept the roads clear.']},
{subject:'the workshop keys',hint:'someone towing a truck alone',question:'Who left the workshop keys with a note: “for whoever comes back”?',clues:['The note in the key box reads: “For whoever comes back. Bring the trucks home.”','Copper Mine workers know the handwriting: neat and slanted, a mechanic’s hand.','The Heat Station gauges were reset by someone who knew the ashfall schedule by heart.','Red Viaduct graffiti shows a wrench inside a heart, the old workshop’s logo.','At South Quarry, a spare engine is wrapped in a blanket and tagged “Truck 7.”','Glass Flats trackers saw someone towing a broken truck toward the Firebreak, alone.','The Firebreak crew says a retired mechanic helps every evacuation, then vanishes.','Old Foundry tools are freshly oiled and laid out exactly the way Dad said his teacher did.','Ember Ridge radio: “Truck 7 is ready. Tell Mara her dad’s teacher kept her promise.”','At Safe Crossing, Marisol, the mechanic who taught Dad, waits beside Truck 7. Every evacuation vehicle is ready to leave.']},
{subject:'the old river map',hint:'a child holding a folded map',question:'Where does the old river map lead?',clues:['In a dry jar at River Steps: a hand-drawn map with every family’s house marked.','Moss Gate’s stones are painted with the same symbols as the map.','Temple Road’s elders say people who rebuilt after another flood drew the map long ago.','At Canopy Camp, a child adds her own house to the map in crayon.','The Stone School teacher planned every safe walking route from the map.','The Broken Aqueduct is crossed out on the map. Someone knew it would fail.','Behind the Garden Wall, a second map: every rescue you’ve made, all the way from Desert County.','Green Bridge’s keeper says the second map was mailed from a garage in Desert County.','At Hidden Dock, Jun admits it: he has mapped every family you brought home since the first night.','Home Road ends at the riverside home, where everyone you rescued across five worlds has gathered. Nobody drives home alone.']}
];
const sightings=['Before the smoke closed in, I saw {hint} heading toward {next}.','When the cable came down, {hint} was already stopped on the far side, waiting it out. Whoever it was knew the safe rule.','From the dry ground I watched {hint} pass by. It didn’t risk the water either.','That stranger on the radio was asking about {subject}. Jun says nobody we know sent it.','The message wanted the code for {hub}. Someone else is looking for {subject} too.','Taped to the sealed case: a hand-drawn arrow pointing to {next}. Same hand as the last note.','By the gate, someone was humming the old song from {hub}. Only family knows that song.','Someone chalked on the closed crossing: “Wait. Help is coming.” Then I saw {hint}.','Right before you came, someone lit a lantern on that landmark. I think it was {hint}.'];
const talks=[['{name} is still out there.','Then we turn back.'],['The cable cut off {site}.','We take the long way. We always do.'],['{name} is on dry ground, but the water’s rising.','Then we get there before it does.'],['What if that radio message is a trap?','Then we check it, and we still go.'],['Their phone is almost dead.','Then we’re their signal now.'],['It’s just a sealed case.','It’s someone’s medicine. That makes it everything.'],['They’re waiting by the gate, on the safe side.','Good. Let’s keep it that way.'],['The shortcut’s broken.','Then we drive the long road. Together.'],['I know that landmark. Dad used to take us there.','Then show me the way.'],['Last call in {site}.','Nobody gets left behind. Not tonight.']];
const roles=['medic','mechanic','teacher','radio volunteer','delivery driver','shelter cook','bridge worker','ferry operator','caregiver','rescue volunteer'];
const styles=['rendezvous','steady pickup','two neighbors','supply recovery','quiet approach'];
let active=false,entry=null,phase='objective',hold=0,people=[],home=null,joined=0,timer=0,done=false,quote=0,clock=0;
function templateStory(w,l){const a=arcs[w],chapter=Math.floor((l-1)/10),person=(l-1)%10,b=beats[person];return{id:`${w}-${l}`,title:`${a.sites[chapter]}: ${b[0]}`,name:a.people[person],companion:a.people[(person+1)%10],role:roles[(person+chapter)%10],site:a.sites[chapter],hub:a.hub,lesson:b[2],motive:`${a.people[person]}, a ${roles[(person+chapter)%10]}, is waiting at ${a.sites[chapter]}. ${b[1]}`,arc:`Mara and Jun must ${a.need}.`,outcome:a.end,style:styles[(chapter+person+w)%styles.length],world:w,level:l,...mystery(w,chapter,person)}}
// Authored worlds (dist/story-*.js) replace the template text level by level; other worlds keep the templates.
const lessons={smoke:'Meet people beyond the smoke; leave fire response to trained crews.',cable:'Keep away from fallen cables and use a different route.',water:'Use a dry pickup point; do not enter floodwater to make a shortcut.',radio:'Confirm changed pickup instructions through a known contact.',code:'Keep passwords and access codes private, even when a message sounds urgent.',medicine:'Transport sealed supplies; let qualified people handle medicines.',gate:'Arrange pickup away from the water; leave water rescue to trained responders.',crossing:'A closed crossing is a reason to reroute, not a challenge to beat.',landmark:'Agree on a visible landmark and confirm where help is meeting you.',verify:'Verify the pickup and keep the group together at the meeting point.',heat:'In extreme heat, wait in shade, sip water and ask for help before you feel unwell.',dust:'In a dust storm, pull well off the road, switch lights off and wait it out.',rockfall:'Stay clear of loose cliffs and fallen rock; a blocked road means find another way.',night:'Stranded at night? Stay with your vehicle, stay visible and let help find you.',cold:'In freezing cold, get out of the wind, add layers and stay together until help arrives.',avalanche:'Keep out of avalanche paths after heavy snow and wait for the all-clear.',ice:'Never cross a frozen lake or river to save time; go around.',ash:'When ash falls, cover your nose and mouth and shelter in a building or closed vehicle.',mudslide:'After heavy rain, keep away from steep muddy slopes and listen for rumbling.',tide:'In a storm surge, stay off piers and seawalls and move to higher ground.'};
function authored(w,l){const book=(typeof globalThis!=='undefined'?globalThis:{}).RescueStories?.[w],ch=book?.chapters?.[Math.floor((l-1)/10)],v=ch?.levels?.[(l-1)%10];return v?{ch,v}:null}
function story(w,l){const base=templateStory(w,l),a=authored(w,l);if(!a)return base;const {ch,v}=a,m=mysteries[w];
return{...base,title:`${base.site}: ${v.t}`,name:v.n,companion:v.w||base.companion,role:v.r,lesson:lessons[v.h]||base.lesson,motive:v.s,arc:ch.arc,chapterTitle:ch.title,
style:v.w?'two neighbors':v.sup?'supply recovery':['rendezvous','steady pickup','quiet approach'][(l+w)%3],
sighting:base.finale?base.clue:v.x,line:v.l,hook:base.finale?`Chapter ${base.chapter} finale · ${ch.title}: the truth about ${m.subject} is waiting at ${base.site}.`:`${v.n} ${v.k}. Bring ${v.n} home to hear it.`,talk:[v.j,v.m]}}
function mystery(w,chapter,person){const a=arcs[w],m=mysteries[w],name=a.people[person],next=chapter<9?a.sites[chapter+1]:a.hub,fill=t=>t.replace(/{hint}/g,m.hint).replace(/{next}/g,next).replace(/{subject}/g,m.subject).replace(/{hub}/g,a.hub).replace(/{name}/g,name).replace(/{site}/g,a.sites[chapter]),finale=person===9;return{finale,chapter:chapter+1,subject:m.subject,question:m.question,clue:finale?m.clues[chapter]:'',sighting:finale?m.clues[chapter]:fill(sightings[person]),hook:finale?`Chapter ${chapter+1} finale: the truth about ${m.subject} is waiting at ${a.sites[chapter]}.`:`${name} saw something tied to ${m.subject}. Bring ${name} home to hear it.`,talk:talks[person].map(fill)}}
function eligible(){return !(typeof R!=='undefined'&&R.active)&&!(typeof V!=='undefined'&&V.active)&&!(typeof Intro!=='undefined'&&Intro.active)}
function prepare(point){active=eligible();entry=active?story(C.world,C.level):null;phase='objective';hold=joined=timer=quote=clock=0;done=false;people=[];home={x:0,y:300};if(active){const count=entry.style==='two neighbors'?2:1;for(let i=0;i<count;i++)people.push({...point(),taken:false})}}
function brief(go){if(!eligible()){go();return}const e=story(C.world,C.level),d=document.createElement('dialog');d.className='story-brief';d.innerHTML=`<div class="eyebrow">RESCUE DISPATCH · WORLD ${e.world+1} · LEVEL ${e.level}${e.chapterTitle?' · '+e.chapterTitle.toUpperCase():''}</div><div class="story-who"><span data-portrait></span><div><h2>${e.title}</h2><small>${e.name.toUpperCase()} · ${e.role.toUpperCase()}</small></div></div><p class="story-hook">${e.hook}<br><small>${e.finale?'CLUE '+e.chapter+'/10':'MYSTERY'} · ${e.question}</small></p><p>${e.motive}</p><p class="hero-brief">${typeof Hero!=='undefined'?Hero.call(e):'Only you can reach '+e.site+' before the patrols seal it.'}</p><blockquote>Jun: “${e.talk[0]}”<br>Mara: “${e.talk[1]}”</blockquote><p class="rescue-safety-cue"><b>SAFE RESCUE CUE</b><br>${e.lesson}</p><p><b>THE PLAN</b><br>${C.objectiveText()} first. Then ${e.style==='two neighbors'?'bring '+e.name+' and '+e.companion+' aboard':e.style==='supply recovery'?'recover the supply bundle for '+e.name:'pick up '+e.name} and reach ${e.hub}. Pickup cover reduces incoming damage inside the zone; new patrols pause while you collect passengers.</p><button class="primary" data-go>I’M ON MY WAY, ${e.name.toUpperCase()} ↗</button><button class="secondary" data-close>BACK</button>`;const close=()=>{d.close();d.remove()};d.querySelector('[data-go]').onclick=()=>{close();go()};d.querySelector('[data-close]').onclick=close;d.addEventListener('cancel',()=>d.remove());const slot=d.querySelector('[data-portrait]');if(slot&&typeof People!=='undefined')slot.replaceWith(People.portrait(lookOf(e.world,e.name,e.role),'worried',84));document.body.append(d);d.showModal()}
function lookOf(w,name,role){return People.look(name,role,w)}
function target(){return !active||done?null:phase==='return'?home:people.find(p=>!p.taken)}
function armor(){const p=target();return active&&eligible()&&phase==='pickup'&&p&&Math.hypot(player.x-p.x,player.y-p.y)<100?.45:1}
function pickupDuration(){return entry.style==='steady pickup'?2.3:entry.style==='quiet approach'?1.8:entry.style==='supply recovery'?.8:1.2}
function speed(){const p=target();return active&&eligible()&&phase==='pickup'&&p&&Math.hypot(player.x-p.x,player.y-p.y)<100?.22:1}
function tick(dt,objectiveDone){if(!active||!eligible())return objectiveDone;timer-=dt;clock+=dt;quote=Math.max(0,quote-dt);if(phase==='objective'&&objectiveDone){phase='pickup';hold=0;sound(680,.1)}if(phase==='pickup'){const p=target(),r=entry.style==='quiet approach'?65:85;const near=p&&Math.hypot(player.x-p.x,player.y-p.y)<r;const duration=pickupDuration();if(near){hold+=dt;if(hold>=duration){p.taken=true;joined++;hold=0;sound(850,.1);if(typeof burst==='function')burst(p.x,p.y,'#ffd173',16);const who=entry.style==='two neighbors'&&joined===1?entry.name:joined===2?entry.companion:entry.name;if(typeof toast==='function')toast(entry.style==='supply recovery'?`SUPPLIES SECURED FOR ${entry.name.toUpperCase()} · HERO MOVE`:typeof Hero!=='undefined'?Hero.pickup(entry,who):`${who.toUpperCase()} IS SAFE WITH YOU`);if(joined===people.length){phase='return';quote=8;timer=0}}}else hold=0}if(phase==='return'&&Math.hypot(player.x-home.x,player.y-home.y)<95){done=true;phase='home'}if(timer<=0){timer=P.config.hud;const p=target(),a=p?Math.atan2(p.y-player.y,p.x-player.x)*180/Math.PI+90:0;const line=phase==='objective'?`${entry.name} is waiting · ${C.objectiveText()}`:phase==='pickup'?`${entry.style==='supply recovery'?'RECOVER SUPPLIES FOR':'RESCUE'} ${entry.name.toUpperCase()} · ${joined}/${people.length} aboard · PICKUP COVER`:`${entry.name.toUpperCase()} IS WITH YOU · BRING THEM HOME, HERO`;$('rescueRibbon').hidden=false;const html=`<b>${entry.title}</b><span>${line}</span>${quote>0?`<em>${entry.name}: “${entry.line||entry.sighting}”</em>`:''}${phase!=='objective'&&p?`<small>↑ ${Math.round(Math.hypot(p.x-player.x,p.y-player.y))}m · ${phase==='pickup'?'Stay in the amber zone':'Follow the green home signal'}</small><i style="transform:rotate(${a}deg)">↑</i>`:''}`;if($('rescueRibbon').innerHTML!==html)$('rescueRibbon').innerHTML=html}return done}
function guests(){const start=Math.floor((entry.level-1)/10)*10,out=[];for(let i=0;i<10&&out.length<3;i++){const l=start+i+1;if(l!==entry.level&&C.data.rescueClears?.[entry.world+'-'+l]){const g=story(entry.world,l);out.push(People.look(g.name,g.role,entry.world))}}return out}
function lit(){const n=Object.keys(C.data.rescueClears||{}).filter(k=>k.startsWith(entry.world+'-')).length;return Math.min(4,Math.ceil(n/4))}
function draw(g){if(!active||!eligible()||typeof People==='undefined')return;People.home(g,home.x,home.y,entry.world,lit(),clock,guests(),phase==='return'||done);
if(phase==='return'){g.strokeStyle='#74ddbe';g.lineWidth=3;g.beginPath();g.arc(home.x,home.y,95,0,Math.PI*2);g.stroke();People.tag(g,home.x,home.y-112,`BRING ${entry.name.toUpperCase()} HOME`,'#74ddbe')}
if(done)return;for(let i=0;i<people.length;i++){const p=people[i];if(p.taken)continue;const name=entry.style==='two neighbors'&&i===1?entry.companion:entry.name,lk=People.look(name,i===1?roles[(roles.indexOf(entry.role)+3)%10]:entry.role,entry.world);
if(phase==='pickup'){g.strokeStyle='#ffd173';g.lineWidth=3;g.beginPath();g.arc(p.x,p.y,85,0,Math.PI*2);g.stroke()}
if(entry.style==='supply recovery')People.crate(g,p.x,p.y,clock);else People.person(g,p.x,p.y+14,clock+i,lk,phase==='pickup'?'waiting':'idle');
People.tag(g,p.x,p.y-78,phase==='pickup'?`${name.toUpperCase()} · ${entry.style==='supply recovery'?'SUPPLIES':lk.role.toUpperCase()}`:`${name.toUpperCase()} · WAITING`,phase==='pickup'?'#ffd173':'#8aa0b4');
if(hold>0&&p===target()){g.strokeStyle='#fff';g.lineWidth=4;g.beginPath();g.arc(p.x,p.y,30,-Math.PI/2,-Math.PI/2+Math.min(1,hold/pickupDuration())*Math.PI*2);g.stroke()}}}
// Result screen: portrait, what they saw, and how many people the player has brought home.
function result(count){if(!entry)return null;const box=document.createElement('div');box.className='rescue-result';if(typeof People!=='undefined')box.append(People.portrait(lookOf(entry.world,entry.name,entry.role),'happy',76));const text=document.createElement('div');
text.innerHTML=`${typeof Hero!=='undefined'?Hero.head(entry,arcs[entry.world].place):''}<p class="rescue-homecoming">${entry.name}${entry.style==='two neighbors'?' and '+entry.companion:''} made it to ${entry.hub}. ${entry.outcome}</p>${entry.line?`<p class="rescue-line">“${entry.line}”</p>`:''}<blockquote class="rescue-sighting">${entry.finale?`<b>CLUE ${entry.chapter}/10 FOUND</b>`:`<b>${entry.name.toUpperCase()} SAW SOMETHING</b>`}“${entry.sighting}”</blockquote>${typeof Hero!=='undefined'?Hero.foot(count,arcs[entry.world].place):`<p class="rescue-hero">You turned back for them. <b>${count} ${count===1?'person is':'people are'} home in ${arcs[entry.world].place}</b> because of you.</p>`}<small class="rescue-lesson">${entry.lesson}</small>`;box.append(text);return box}
function teaser(w,l){const n=story(w,l);return n.chapter!==story(w,l-1).chapter?`NEXT CHAPTER · ${n.site}: ${n.name} is waiting. ${n.question}`:n.finale?`NEXT · CHAPTER FINALE at ${n.site}: the truth about ${n.subject}.`:`NEXT · ${n.name} at ${n.site} saw something tied to ${n.subject}.`}
function init(){const e=document.createElement('aside');e.id='rescueRibbon';e.hidden=true;document.body.append(e)}
function hide(){const e=$('rescueRibbon');if(e)e.hidden=true}
return{story,prepare,brief,tick,draw,result,teaser,speed,armor,pursuit:()=>!active||!eligible()||phase!=='pickup',init,hide,get active(){return active&&eligible()},get entry(){return entry},get phase(){return phase},get targets(){return people},get home(){return home}};
})();
